from class12_quran_common import BOOK, Builder, rec, V


def p79():
    b = Builder()
    b.h('Lesson 8 — Surah al-Ma\'idah (verses 78 to 120)', 'سبق ۸ — سُوْرَةُ الْمَآئِدَةِ (آیات: ۷۸ تا ۱۲۰)', '۸ لوست — سورة المائدة (آیتونه ۷۸ تر ۱۲۰)')
    V(b, 5, 78, 'بنی اسرائیل میں سے جنھوں نے کفر کیا ان پر لعنت کی گئی داؤد (علیہ السلام) اور عیسیٰ ابنِ مریم (علیہ السلام) کی زبان سے ایسا اس لیے ہوا کہ انھوں نے نافرمانی کی اور وہ حد سے بڑھ جایا کرتے تھے۔',
      'له بني اسرائیلو څخه پر هغو کسانو چې کفر یې وکړ، د داود (علیه السلام) او عیسی ابن مریم (علیه السلام) په ژبه لعنت وشو؛ دا ځکه چې نافرماني یې وکړه او له حده به اوښتل.')
    V(b, 5, 79, 'وہ ایک دوسرے کو اُس بُرائی سے نہیں روکا کرتے تھے جو وہ کرتے تھے یقیناً بُرا تھا جو کچھ وہ کیا کرتے تھے۔',
      'هغوی به یو بل له هغې بدۍ نه منع کول چې کوله به یې؛ یقیناً بد و هغه څه چې کول به یې.')
    V(b, 5, 80, 'آپ ان میں سے بہت سے لوگوں کو دیکھتے ہیں کہ وہ انھیں اپنا دوست بناتے ہیں جنھوں نے کفر کیا یقیناً بُرا ہے جو انھوں نے خود اپنے لیے آگے بھیجا جس سے اللہ اُن پر ناراض ہوا اور وہ ہمیشہ عذاب میں رہنے والے ہیں۔',
      'تاسو له هغوی ډېر خلک وینئ چې کافران خپل دوستان نیسي؛ یقیناً بد دی هغه څه چې پخپله یې د ځان لپاره مخکې لېږلي، چې له امله یې الله پر هغوی ناراض شو، او هغوی به تل په عذاب کې وي.')
    V(b, 5, 81, 'اور اگر وہ اللہ پر اور (اس) نبی پر اور اُس (کتاب) پر جو ان کی طرف نازل کی گئی ایمان لے آتے تو ان (کافروں) کو دوست نہ بناتے لیکن ان میں سے اکثر لوگ نافرمان ہیں۔',
      'او که پر الله، پر (دې) نبي او پر هغه (کتاب) یې ایمان راوړی وای چې دوی ته نازل شوی، نو هغه (کافران) به یې دوستان نه وای نیولي؛ خو د هغوی ډېری خلک نافرمانه دي.')
    V(b, 5, 82, 'آپ اہلِ ایمان کی عداوت میں ضرور سب سے زیادہ سخت یہود اور مشرکین کو پائیں گے اور آپ اہلِ ایمان سے دوستی میں ضرور سب سے زیادہ قریب (ان لوگوں کو) پائیں گے جنھوں نے کہا تھا کہ ہم نصاریٰ ہیں یہ اس لیے کہ ان میں علماء اور درویش ہیں اور یہ (اس لیے) کہ وہ تکبر نہیں کرتے۔',
      'تاسو به د مؤمنانو په دښمنۍ کې خامخا تر ټولو سخت یهود او مشرکان ومومئ، او له مؤمنانو سره په دوستۍ کې به خامخا تر ټولو نږدې (هغه کسان) ومومئ چې ویل یې «موږ نصارا یو»؛ دا ځکه چې په هغوی کې علماء او درویشان دي، او دا (ځکه) چې هغوی کبر نه کوي.')
